<?php $compact=$compact ?? false; $f=$filters ?? []; ?>
<form class="property-search <?= $compact?'search-compact':'' ?>" action="<?= url('properties') ?>" method="get" role="search" aria-label="Find a property">
<?php if(!config('pretty_urls')): ?><input type="hidden" name="route" value="properties"><?php endif; ?>
<div class="search-tabs" role="group" aria-label="Listing type"><?php foreach(['sale'=>'Buy','rent'=>'Rent',''=>'All properties'] as $value=>$label): ?><label><input type="radio" name="deal" value="<?= $value ?>" <?= ($f['deal'] ?? 'sale')===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach; ?></div>
<div class="search-fields">
<div class="search-field search-keyword"><label for="search-q-<?= $compact?'inner':'hero' ?>">What are you looking for?</label><div><?= icon('search') ?><input id="search-q-<?= $compact?'inner':'hero' ?>" type="search" name="q" value="<?= e($f['q'] ?? '') ?>" placeholder="Home, neighborhood, or listing ID"></div></div>
<div class="search-field"><label for="search-location-<?= $compact?'inner':'hero' ?>">Location</label><select name="location" id="search-location-<?= $compact?'inner':'hero' ?>"><option value="">All locations</option><?php foreach(Database::all('SELECT name,slug FROM locations ORDER BY name') as $l): ?><option value="<?= e($l['slug']) ?>" <?= ($f['location'] ?? '')===$l['slug']?'selected':'' ?>><?= e($l['name']) ?></option><?php endforeach; ?></select></div>
<div class="search-field"><label for="search-category-<?= $compact?'inner':'hero' ?>">Property type</label><select name="category" id="search-category-<?= $compact?'inner':'hero' ?>"><option value="">All property types</option><?php foreach(Database::all('SELECT name,slug FROM categories ORDER BY name') as $c): ?><option value="<?= e($c['slug']) ?>" <?= ($f['category'] ?? '')===$c['slug']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div>
<div class="search-field search-budget"><label for="search-price-<?= $compact?'inner':'hero' ?>">Maximum budget</label><select name="max_price" id="search-price-<?= $compact?'inner':'hero' ?>"><option value="">Any budget</option><?php foreach([10000000=>'₦10 million',50000000=>'₦50 million',100000000=>'₦100 million',250000000=>'₦250 million',500000000=>'₦500 million',1000000000=>'₦1 billion'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($f['max_price'] ?? '')==(string)$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div>
<button class="btn btn-primary search-submit" type="submit"><?= icon('search') ?><span>Find a property</span></button>
</div>
<?php if(!$compact): ?><div class="search-popular"><span>Popular searches</span><a href="<?= url('properties',['category'=>'apartments']) ?>">Apartments</a><a href="<?= url('properties',['location'=>'lekki']) ?>">Homes in Lekki</a><a href="<?= url('properties',['category'=>'land']) ?>">Land for sale</a><?= icon('shield') ?><small>A considered search. A confident next step.</small></div><?php endif; ?>
</form>
